const mobileOverlay = {
  sidebar: 'md:relative collapsed && max-md:hidden !collapsed && max-md:fixed max-md:inset-y-0 max-md:left-0 max-md:z-50',
  backdrop: '!collapsed && fixed inset-0 z-40 bg-black/50 md:hidden'
}; // Shown only when !collapsed on mobile, hidden on desktop

const selected = useAppStore(s => s.selectedProject);
const projects = useAppStore(s => s.projects);
const handleSelect = (id: string) => useAppStore.getState().setSelectedProject(id);
<DropdownMenu>
  <DropdownMenuTrigger>{selected?.name || 'Select'}</DropdownMenuTrigger>
  {projects.map(p => <DropdownMenuItem onClick={() => handleSelect(p.id)}>{p.name}</DropdownMenuItem>)}
</DropdownMenu>
